import React, { Component } from "react";
import axios from "axios";
import "./Service.css";
import { Progress } from 'react-sweet-progress';
import "react-sweet-progress/lib/style.css";

class Service extends Component {
    constructor(props) {
        super(props);
        this.state = {
            servicePage: null,
            contentArray: [],
            loading: false,
            progress: 0,
            error: null,
            selectedInterval: '',
        };
    }

    componentDidMount() {
        fetch("http://localhost:3001/pages/6", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({}),
        })
            .then((response) => response.json())
            .then((page) => {
                let contentArray = [];
                try {
                    contentArray = Array.isArray(page.content)
                        ? page.content
                        : JSON.parse(page.content);
                } catch (error) {
                    console.error('Error parsing content:', error);
                }
                this.setState({ servicePage: page, contentArray });
            })
            .catch((error) => this.setState({ error: "Error fetching data" }));
    }

    fetchData = async () => {
        this.setState({ loading: true, progress: 0 });

        try {
            const response = await axios.post("http://localhost:3001/trackipetmap", {
                pet_id: 1, // Use the correct pet_id
                onDownloadProgress: (e) => {
                    const total = e.total || 100;
                    const current = e.loaded;
                    const progress = Math.round((current / total) * 100);
                    this.setState({ progress });
                }
            });

            const { lat, lng } = response.data;
            const interval = setInterval(() => {
                this.setState((prevState) => {
                    const newProgress = Math.min(prevState.progress + 10, 100);
                    if (newProgress >= 100) {
                        clearInterval(interval);
                        setTimeout(() => { window.location.href = `/map?lat=${lat}&lng=${lng}&pet_id=1` }, 1000); // Use the correct pet_id
                    }
                    return { progress: newProgress };
                });
            }, 200);
        } catch (error) {
            console.error(error);
            this.setState({ error: "Error fetching location data" });
        } finally {
            this.setState({ loading: false });
        }
    };

    handleIntervalChange = (event) => {
        this.setState({ selectedInterval: event.target.value });
    }

    showHistory = async () => {
        const { selectedInterval } = this.state;
        if (!selectedInterval) {
            alert('Please select a time period.');
            return;
        }

        try {
            const response = await axios.get(`http://localhost:3001/locations/history`, {
                params: {
                    pet_id: 1, // Use the correct pet_id
                    interval: selectedInterval
                }
            });

            const points = response.data;
            // Handle displaying points on the map here

        } catch (error) {
            console.error("Error fetching historical data:", error);
        }
    }

    render() {
        const { servicePage, contentArray, loading, progress, error, selectedInterval } = this.state;

        if (error) return <div>{error}</div>;
        if (!servicePage) return <div>PAGE NOT FOUND</div>;

        return (
            <div className="container">
                {loading ? (
                    <div>
                        <Progress type="circle" percent={progress} />
                    </div>
                ) : (
                    <div className="content-section">
                        {contentArray.length > 0 ? (
                            <>
                                <p className="Hello">{contentArray[0]?.p || contentArray[0]}</p>
                                <p className="Miss">{contentArray[1]?.p || contentArray[1]}</p>
                            </>
                        ) : (
                            <div>No content available</div>
                        )}

                        <img src="./media/dog1.png" alt="Dog" className="dog-image" />

                        <button className="location" onClick={this.fetchData}>
                            Pet's Location
                        </button>

                        <div className="dropdown">
                            <select value={selectedInterval} onChange={this.handleIntervalChange}>
                                <option value="">Select Time Interval</option>
                                {[...Array(24)].map((_, i) => (
                                    <option key={i} value={`last ${i + 1} hour${i > 0 ? 's' : ''}`}>{`Last ${i + 1} hour${i > 0 ? 's' : ''}`}</option>
                                ))}
                                <option value="last day">Last Day</option>
                                <option value="last week">Last Week</option>
                            </select>
                        </div>

                        <button className="show-history" onClick={this.showHistory}>
                            Show History
                        </button>
                    </div>
                )}
            </div>
        );
    }
}

export default Service;
